document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('.briefing-card');const start=document.querySelector('#startBriefing');if(!form||!start)return;const extra=document.createElement('div');extra.innerHTML='<label>Quando você vem?<input id="tripDate" type="month"></label><label>Quantas pessoas viajam?<select id="party"><option>1 pessoa</option><option selected>2 pessoas</option><option>3 a 4 pessoas</option><option>5 ou mais pessoas</option></select></label><label>Qual faixa de orçamento por pessoa?<select id="budget"><option>Até R$ 300</option><option selected>R$ 300 a R$ 700</option><option>R$ 700 a R$ 1.500</option><option>Acima de R$ 1.500</option></select></label>';form.insertBefore(extra,start);start.onclick=()=>{const profile={days:days.value,stay:stay.value,hotel:hotel.value,boat:boat.value,tripDate:tripDate.value,party:party.value,budget:budget.value};localStorage.setItem('angra-briefing',JSON.stringify(profile));location.reload()}});
